# test_binary_search.py

import pytest

# Replace "your_module" with the module where binary_search is defined.
from your_module import binary_search


@pytest.mark.parametrize(
    "arr,target,expected",
    [
        ([1, 3, 5, 7, 9], 5, 2),          # middle element
        ([1, 3, 5, 7, 9], 1, 0),          # first element
        ([1, 3, 5, 7, 9], 9, 4),          # last element
        ([2, 4, 6, 8], 8, 3),             # even-length list
        ([-10, -3, 0, 4, 12], -3, 1),     # negative numbers
    ],
)
def test_binary_search_finds_existing_values(arr, target, expected):
    assert binary_search(arr, target) == expected


@pytest.mark.parametrize(
    "arr,target",
    [
        ([1, 3, 5, 7, 9], 4),    # between values
        ([1, 3, 5, 7, 9], 0),    # smaller than all values
        ([1, 3, 5, 7, 9], 10),   # larger than all values
    ],
)
def test_binary_search_returns_minus_one_when_target_not_found(arr, target):
    assert binary_search(arr, target) == -1


@pytest.mark.parametrize(
    "arr,target,expected",
    [
        ([], 1, -1),        # empty list
        ([10], 10, 0),      # single element found
        ([10], 5, -1),      # single element not found
    ],
)
def test_binary_search_edge_cases(arr, target, expected):
    assert binary_search(arr, target) == expected


def test_binary_search_with_duplicates_returns_valid_matching_index():
    arr = [1, 2, 2, 2, 3]

    result = binary_search(arr, 2)

    assert result in {1, 2, 3}
    assert arr[result] == 2


def test_binary_search_does_not_modify_input_list():
    arr = [1, 2, 3, 4, 5]
    original = arr.copy()

    binary_search(arr, 3)

    assert arr == original


@pytest.mark.parametrize(
    "arr,target",
    [
        (None, 1),              # arr must be list-like
        ([1, 2, 3], None),      # target must be comparable
        ([1, 2, 3], "2"),       # incompatible target type
        ([1, "two", 3], 2),     # incompatible element type
    ],
)
def test_binary_search_raises_type_error_for_invalid_inputs(arr, target):
    with pytest.raises(TypeError):
        binary_search(arr, target)
```

Note: these tests assume the input list is sorted in ascending order. The current implementation does not validate that precondition, so unsorted input is not treated as an error.
